{
  "probability": 0.95,
  "range_low": 0.88,
  "range_high": 0.99,
  "summary": [
    "Early-2026 data show a high death pace (606 by late February 2026), implying feasibility of reaching 900 by end-April if the pace persists.",
    "Key drivers include weather-driven mortality spikes and rising crossings in North Africa corridors, which push the probability upward.",
    "Reporting lag and upward revisions could further lift the tally, while SAR/policy actions could moderate the outcome.",
    "Overall, the 900+ toll by April remains plausible but uncertain given data gaps and potential shocks."
  ],
  "confidence": "high",
  "narrative": "The current evidence base shows an unusually fast start to 2026 Mediterranean fatalities. Given the pace through February and persistent risk factors (storms, crossings), a 900-death toll by end-April is plausible, with substantial uncertainty from data gaps and potential mitigation actions.",
  "justification": {
    "anchor": {
      "probability": 0.75,
      "basis": "Using the reference class of annual Mediterranean death tolls, the early-2026 pace suggests a meaningful chance of hitting 900 by April; 0.75 is a reasonable starting anchor before explicit updates."
    },
    "factor_updates": [
      {
        "factor": "Pace of deaths in 2026 through February (early-year tempo)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by Feb 23–24 implies that extending that pace through March–April could yield around 900 total by end-April, making the target plausible."
      },
      {
        "factor": "Weather-driven shipwreck risk (e.g., Cyclone Harry)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Severe storms were a major contributor early 2026; continued weather risk increases the death toll risk in the coming months."
      },
      {
        "factor": "Data reporting lag and upward revisions to counts",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Counts have revised upward in February; additional revisions could push totals higher than current tallies."
      },
      {
        "factor": "Seasonal/early-year dynamics on the Central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Across 2014–2026, Central Mediterranean remains the deadliest route with high volatility; early 2026 appeared unusually lethal."
      },
      {
        "factor": "Mitigation via search-and-rescue and policy actions",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stronger SAR and policy actions could reduce deaths, offsetting some upward pressure."
      }
    ],
    "synthesis_rationale": "We start with a 0.75 anchor from the forecast evidence. The four upward factors collectively add expectation of higher counts into March–April; a single moderate downward factor (SAR improvements) tempers the risk. The resulting calibrated posterior is 0.95, with a range reflecting substantial but not complete uncertainty due to data gaps and possible weather shocks."
  }
}

{
  "probability": 0.95,
  "range_low": 0.90,
  "range_high": 0.98,
  "summary": [
    "606 deaths/missing in 2026 by late February suggests a high baseline pace into March–April.",
    "Weather-driven mortality risk and increased departures from North Africa raise upside risk to hitting 900 by end-April.",
    "Data reporting lags and potential upward revisions could further increase observed toll, while SAR/policy changes could temper it."
  ],
  "confidence": "high",
  "narrative": "The early-2026 Mediterranean death toll has been elevated, with about 606 fatalities by February. If the pace persists into March–April, reaching 900 by end-April is plausible, and Bayesian updating yields a high posterior probability of 95% despite data gaps.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Reference class: Central Mediterranean migrant deaths per year; early-February 2026 tallies imply a high annual pace but are not yet a full-year total; anchoring at 0.60 reflects a plausible starting stance given the elevated start to 2026."
    },
    "factor_updates": [
      {
        "factor": "Pace of deaths in 2026 through February",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 fatalities by Feb 23–24 imply a high tempo, making the 900-year-end-April target more likely if March–April remain at or above February levels."
      },
      {
        "factor": "Weather-driven shipwreck risk (storms/Cyclone Harry)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Severe weather increases crossing risk, potentially sustaining high death tolls into spring."
      },
      {
        "factor": "Data reporting lag and upward revisions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "IOM updates counts as new information arrives, raising observed totals and the probability of 900 by April."
      },
      {
        "factor": "Seasonal/early-year dynamics on Central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Analyses describe 2026 as potentially the deadliest year, implying elevated risk into spring."
      },
      {
        "factor": "Mitigation via SAR capacity and policy actions",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stronger SAR and safer pathways could reduce fatalities, reducing the chance of hitting 900."
      }
    ],
    "synthesis_rationale": "Starting from a 0.60 anchor, the dominant upward factors (pace, weather, reporting lags, seasonality) outweigh the moderating downward factor (SAR improvements). The combined updates push the posterior toward 0.95, but substantial uncertainty remains due to data gaps and potential shocks; the interval 0.90–0.98 captures this calibrated uncertainty."
  }
}

{
  "probability": 0.20,
  "range_low": 0.15,
  "range_high": 0.30,
  "summary": [
    "As of late February 2026, about 606 Mediterranean deaths/missing were recorded for 2026, suggesting a high early-year pace but not guaranteed to continue.",
    "Hitting 900 by end-March requires roughly 294 additional deaths in March, which is plausible only under an extreme monthly surge.",
    "Weather shocks (storms, Cyclone Harry) and ongoing departures raise the upside risk, while SAR improvements and policy actions could reduce fatalities.",
    "There is no published forecast model for March 2026, so uncertainty remains high and the probability is best viewed as a low-probability tail event."
  ],
  "confidence": "low",
  "narrative": "The February tally of 606 deaths signals a historically fast start, but the March requirement to reach 900 by end-March implies an unusually large monthly toll. Without forecast models, the probability remains low but not zero, reflecting uncertainty about weather, SAR capacity, and data revisions.",
  "justification": {
    "anchor": {
      "probability": 0.25,
      "basis": "Reference class: annual Central Mediterranean migrant deaths per year as tracked by IOM Missing Migrants Project, anchored by February 2026 tally (606) and historical dispersion; this anchor yields a conservative baseline given typical monthly patterns and the lack of a March forecast."
    },
    "factor_updates": [
      {
        "factor": "Pace of deaths in 2026 through February (through Feb 23-24)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by late February imply a weather-driven or ongoing high-risk period; sustaining that pace into March would push counts higher, increasing probability of large monthly tolls albeit not guaranteeing 900 by March."
      },
      {
        "factor": "Weather-driven mortality risk (Cyclone Harry and storms)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Severe weather correlates with elevated fatalities; continued meteorological hazards in March could contribute substantial deaths."
      },
      {
        "factor": "Reporting lag and potential upward revisions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "IOM data often revise upward; February tallies rose from 524 to 606 within weeks, suggesting more deaths could be counted later."
      },
      {
        "factor": "SAR capacity constraints and policy actions reducing deaths",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Increases in SAR presence or safer policy shifts could save lives and reduce the March toll, counterbalancing other risks."
      },
      {
        "factor": "Seasonal/departure dynamics from North Africa corridors",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "High departure volumes increase exposure, raising risk of fatalities if crossings persist."
      }
    ],
    "synthesis_rationale": "The anchor suggests a baseline probability in the low-20s for reaching 900 by end-March. The pace and weather factors add upside risk, and SAR/capacity improvements add downside risk. Given no March-specific forecast and data-lag risks, the final estimate remains a low-probability tail event with a wide and uncertain range."
  }
}
